 const logger = createLogger('slack-acl-sync');
+
+/**
+ * Fail closed immediately when Slack reports that channel membership changed.
+ * The periodic ACL sync remains the sole graph reconciler; this only flips an
+ * existing graph out of the trusted `fresh` state until that sync rebuilds it.
+ * A connection that has never been graphed has no stale membership to trust, so
+ * the update is intentionally a no-op rather than creating an enforcement row.
+ */
+export async function invalidateSlackConnectionAcl(params: {
+  organizationId: string;
+  connectionId: string;
+}): Promise<boolean> {
+  const rows = await getDb()<Array<{ connection_id: string }>>`
+		UPDATE authz_source_acl_state
+		SET freshness_state = 'stale', updated_at = current_timestamp
+		WHERE organization_id = ${params.organizationId}
+		  AND connection_id = ${params.connectionId}
+		RETURNING connection_id
+	`;
+  return rows.length > 0;
+}

